export function normalizeTags(input) {
  const values = Array.isArray(input) ? input : String(input).split(',');
  const seen = new Set();
  const result = [];
  for (const raw of values) {
    const value = String(raw).trim().toLowerCase();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    result.push(value);
  }
  return result;
}

